text:
```yaml
name: Check CLA in PR Description

on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

permissions:
  pull-requests: write

jobs:
  check-cla:
    runs-on: ubuntu-latest
    steps:
      - name: Check for CLA text in PR description
        id: check-cla
        uses: actions/github-script@v7
        with:
          script: |
            const claText = "By submitting this pull request, I confirm that you can use, modify, copy, and redistribute this contribution, under the terms of your choice.";
            const prBody = context.payload.pull_request.body || "";

            if (!prBody.includes(claText)) {
              core.setFailed("PR description is missing the required CLA text.");

              // Post a comment on the PR
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: "This PR is missing the required Contributor License Agreement (CLA) text. Please add the following text to your PR description:\n\n> By submitting this pull request, I confirm that you can use, modify, copy, and redistribute this contribution, under the terms of your choice."
              });
            } else {
              core.info("CLA text found in PR description.");
            }
